import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:slotbookingadmin/core/api/api_services.dart'; import 'package:slotbookingadmin/core/api/api_exception.dart'; import 'package:slotbookingadmin/core/api/session_manager.dart';
class AuthState{final bool isLoading;final String? error;final bool success;const AuthState({this.isLoading=false,this.error,this.success=false});AuthState copyWith({bool? isLoading,String? error,bool? success})=>AuthState(isLoading:isLoading??this.isLoading,error:error,success:success??this.success);}
class AuthNotifier extends StateNotifier<AuthState>{AuthNotifier():super(const AuthState());final _auth=AuthApi(); Future<String?> login({required String email,required String password})async{state=state.copyWith(isLoading:true,error:null);try{final d=await _auth.login(email,password); final u=Map<String,dynamic>.from(d['user']??{}); final role=(d['role']??u['role']??'user').toString(); final status=(u['status']??d['status']??'active').toString(); if(status=='suspended'){await _auth.logout();state=state.copyWith(isLoading:false,error:'Your account has been suspended. Contact support.');return null;} if(status=='pending'){await _auth.logout();state=state.copyWith(isLoading:false,error:'Your account is pending Super Admin approval.');return null;} state=state.copyWith(isLoading:false,success:true);return role;}catch(e){state=state.copyWith(isLoading:false,error:e is ApiException?e.message:'An error occurred. Try again.');return null;}}
 Future<bool> registerAdmin({required String name,required String email,required String password,required String phone})async{state=state.copyWith(isLoading:true,error:null);try{await _auth.register(name:name,email:email,phone:phone,password:password,role:'admin'); await _auth.logout();state=state.copyWith(isLoading:false,success:true);return true;}catch(e){state=state.copyWith(isLoading:false,error:e is ApiException?e.message:'Registration failed: $e');return false;}} void clearError()=>state=state.copyWith(error:null);}
final authNotifierProvider=StateNotifierProvider<AuthNotifier,AuthState>((ref)=>AuthNotifier()); final currentUserRoleProvider=FutureProvider<String?>((ref)async=>SessionManager.currentRole);
